function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 - 60 - 10 * Math.sin(t));
  ctx.lineTo(W / 2 - 20 - 10 * Math.cos(t), H / 2 - 30 - 10 * Math.sin(t));
  ctx.lineTo(W / 2 + 20 + 10 * Math.cos(t), H / 2 - 30 - 10 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 - 25 - 5 * Math.cos(t), H / 2 + 20 + 5 * Math.sin(t), 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 25 + 5 * Math.cos(t), H / 2 + 20 + 5 * Math.sin(t), 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 50 + 10 * Math.sin(t), 20, 0, Math.PI, false);
  ctx.stroke();
  ctx.restore();
}
